#!/usr/bin/env python3
"""Focused ASAN harness for the libsoup content-sniffer look_for_tag boundary.

Extracts the *actual* skip_insignificant_space() and sniff_feed_or_html()
function text from a supplied soup-content-sniffer.c, compiles it with minimal
glib stubs under AddressSanitizer, and feeds a fixture whose length equals
MIN(512, buffer->length).

Modes:
  --expect oob    : pass iff ASAN reports an out-of-bounds access (baseline)
  --expect clean  : pass iff no ASAN error and result is the expected type
"""
from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from pathlib import Path

STUBS = r'''
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef int gboolean;
typedef unsigned long gsize;
typedef struct SoupContentSniffer SoupContentSniffer;
typedef struct { const char *data; gsize length; } SoupBuffer;

#define TRUE 1
#define FALSE 0
#define MIN(a, b) ((a) < (b) ? (a) : (b))

static char *g_strdup (const char *s) {
    size_t n = strlen (s) + 1;
    char *r = malloc (n);
    memcpy (r, s, n);
    return r;
}

static gboolean g_str_has_prefix (const char *str, const char *prefix) {
    return strncmp (str, prefix, strlen (prefix)) == 0;
}
'''

MAIN = r'''
int
main (int argc, char **argv)
{
    const char *path = argv[1];
    FILE *f = fopen (path, "rb");
    long size;
    unsigned char *buf;
    SoupBuffer b;
    char *result;

    if (!f) { fprintf (stderr, "cannot open %s\n", path); return 2; }
    fseek (f, 0, SEEK_END);
    size = ftell (f);
    fseek (f, 0, SEEK_SET);
    buf = malloc ((size_t) size);
    if (fread (buf, 1, (size_t) size, f) != (size_t) size) { return 2; }
    fclose (f);

    b.data = (const char *) buf;
    b.length = (gsize) size;
    result = sniff_feed_or_html (NULL, &b);
    printf ("RESULT:%s\n", result);
    free (result);
    free (buf);
    return 0;
}
'''


def extract_functions(source: str) -> str:
    lines = source.splitlines()
    start = end = None
    for i, line in enumerate(lines):
        if line.startswith("static gboolean") and i + 1 < len(lines) \
                and "skip_insignificant_space (const char" in lines[i + 1]:
            start = i
        if start is not None and line == " text_html:":
            for j in range(i, len(lines)):
                if lines[j] == "}":
                    end = j
                    break
            break
    if start is None or end is None:
        raise SystemExit("could not locate sniffer function text")
    return "\n".join(lines[start:end + 1]) + "\n"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--source", required=True)
    ap.add_argument("--fixture", required=True)
    ap.add_argument("--expect", choices=["oob", "clean"], required=True)
    ap.add_argument("--expected-type", default="text/html")
    ap.add_argument("--workdir", default=None)
    args = ap.parse_args()

    source = Path(args.source).read_text(encoding="utf-8")
    funcs = extract_functions(source)
    workdir = Path(args.workdir) if args.workdir else Path(args.source).resolve().parent
    workdir.mkdir(parents=True, exist_ok=True)
    c_file = workdir / ("focused_%s.c" % args.expect)
    bin_file = workdir / ("focused_%s.bin" % args.expect)
    c_file.write_text(STUBS + "\n" + funcs + "\n" + MAIN, encoding="utf-8")

    cc = subprocess.run(
        ["gcc", "-O0", "-g", "-w", "-fsanitize=address", "-fno-omit-frame-pointer",
         "-o", str(bin_file), str(c_file)],
        capture_output=True, text=True)
    if cc.returncode != 0:
        print(json.dumps({"status": "compile_failed", "stderr": cc.stderr}))
        return 3

    run = subprocess.run(
        [str(bin_file), args.fixture],
        capture_output=True, text=True,
        env={"ASAN_OPTIONS": "detect_leaks=0:abort_on_error=0:exitcode=99"})
    combined = run.stdout + run.stderr
    oob = ("AddressSanitizer" in combined and
           ("heap-buffer-overflow" in combined or "stack-buffer-overflow" in combined or
            "global-buffer-overflow" in combined))
    result_line = [l for l in run.stdout.splitlines() if l.startswith("RESULT:")]

    summary = {
        "status": "ok",
        "expect": args.expect,
        "source": str(Path(args.source).resolve()),
        "extracted_lines": funcs.count("\n"),
        "asan_oob_detected": oob,
        "exit_code": run.returncode,
        "result": result_line[0].split(":", 1)[1] if result_line else None,
        "asan_head": "\n".join(combined.splitlines()[:6]),
    }

    if args.expect == "oob":
        summary["passed"] = oob
    else:
        summary["passed"] = (not oob and run.returncode == 0 and
                             bool(result_line) and result_line[0].split(":", 1)[1] == args.expected_type)
    print(json.dumps(summary, indent=2))
    return 0 if summary["passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

